//! Backups in 1Password via its CLI (`op`), as in home-ca: one Password item
//! per certificate in the Private vault, tagged `renew-certs`, its password
//! generated by 1Password (never on a command line) and the `.p12` attached.

use anyhow::{Context, Result, bail};
use releaseit::sh;
use serde::Deserialize;
use std::path::Path;
use std::process::{Command, Stdio};

pub const VAULT: &str = "Private";
pub const TAG: &str = "renew-certs";

fn op(args: &[&str]) -> Result<String> {
    sh::require_tool("op", "Install the 1Password CLI: brew install 1password-cli")?;
    // No stdin: `op item create/edit` would read piped input as an item template.
    let out = Command::new("op")
        .args(args)
        .stdin(Stdio::null())
        .output()
        .context("failed to start `op`")?;
    if !out.status.success() {
        bail!(
            "1Password CLI failed: op {}\n  {}\n  Unlock the 1Password app and enable \"Integrate with 1Password CLI\".",
            args.iter().take(2).copied().collect::<Vec<_>>().join(" "),
            String::from_utf8_lossy(&out.stderr).trim()
        );
    }
    Ok(String::from_utf8_lossy(&out.stdout).into_owned())
}

#[derive(Deserialize)]
pub struct Summary {
    pub id: String,
    pub title: String,
}

/// The backup items (tagged `renew-certs`) in the Private vault.
pub fn items() -> Result<Vec<Summary>> {
    let json = op(&["item", "list", "--vault", VAULT, "--tags", TAG, "--format", "json"])?;
    serde_json::from_str(&json).context("unexpected `op item list` output")
}

#[derive(Deserialize)]
struct Item {
    id: String,
    #[serde(default)]
    fields: Vec<Field>,
    #[serde(default)]
    files: Vec<serde_json::Value>,
}

#[derive(Deserialize)]
struct Field {
    id: String,
    value: Option<String>,
}

/// An item's id, password, and whether a file is attached.
pub struct Backup {
    pub id: String,
    pub password: String,
    pub has_file: bool,
}

impl Item {
    fn into_backup(self) -> Result<Backup> {
        let password = self
            .fields
            .into_iter()
            .find(|f| f.id == "password")
            .and_then(|f| f.value)
            .filter(|p| !p.is_empty())
            .context("1Password returned no password; unlock 1Password and retry")?;
        Ok(Backup { id: self.id, password, has_file: !self.files.is_empty() })
    }
}

pub fn get(id: &str) -> Result<Backup> {
    let json = op(&["item", "get", id, "--vault", VAULT, "--format", "json"])?;
    serde_json::from_str::<Item>(&json).context("unexpected `op item get` output")?.into_backup()
}

/// Create a Password item with a password generated by 1Password.
pub fn create(title: &str, notes: &str) -> Result<Backup> {
    let json = op(&[
        "item", "create", "--category", "password", "--vault", VAULT, "--title", title, "--tags", TAG,
        "--generate-password=letters,digits,40", &format!("notesPlain={notes}"), "--format", "json",
    ])?;
    serde_json::from_str::<Item>(&json).context("unexpected `op item create` output")?.into_backup()
}

/// Attach `file` to the item, under its file name.
pub fn attach(id: &str, file: &Path) -> Result<()> {
    // '.' would start a section name in op's assignment syntax.
    let name = file.file_name().context("file name")?.to_string_lossy().replace('.', r"\.");
    op(&["item", "edit", id, "--vault", VAULT, &format!("{name}[file]={}", sh::path_str(file)?)]).map(drop)
}
